<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $csrf = App\Core\Security::csrfToken(); ?>
<section><div class="section-heading"><div><p class="eyebrow">Etapa 11</p><h1>Classificacao</h1><p><?= $e($phase['championship_name']) ?> - <?= $e($phase['name']) ?></p></div></div>
<?php if (!empty($message)): ?><p class="success"><?= $e($message) ?></p><?php endif; ?>
<?php if ($canRecalculate): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/classificacao/recalcular')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="phase_id" value="<?= (int) $phase['id'] ?>"><button type="submit">Recalcular</button></form><?php endif; ?>
<?php foreach ($groups as $group): ?><article class="panel"><h2><?= $e($group['name']) ?></h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Equipe</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th><th>PTS</th><th>Aprov.</th><th>Situacao</th><th>Desempate</th></tr></thead><tbody><?php foreach ($table[(int) $group['id']] ?? [] as $row): ?><tr><td><?= (int) $row['position'] ?></td><td><?= $e($row['team_name']) ?></td><td><?= (int) $row['matches_played'] ?></td><td><?= (int) $row['wins'] ?></td><td><?= (int) $row['draws'] ?></td><td><?= (int) $row['losses'] ?></td><td><?= (int) $row['goals_for'] ?></td><td><?= (int) $row['goals_against'] ?></td><td><?= (int) $row['goal_difference'] ?></td><td><?= (int) $row['points'] ?></td><td><?= $e($row['win_percentage']) ?>%</td><td><?= $e($row['situation']) ?></td><td><?= $e($row['separated_by'] ?: '-') ?></td></tr><?php endforeach; ?></tbody></table></div></article><?php endforeach; ?>
<?php if ($canGenerate): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/mata-mata/gerar')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="phase_id" value="<?= (int) $phase['id'] ?>"><button type="submit">Gerar mata-mata</button></form><?php endif; ?></section>
